    KETERANGAN = s.KETERANGAN
WHEN NOT MATCHED THEN INSERT (ID_PERKIRAAN, ID_MODEL, AWAL_PEKAN_SASARAN, TANGGAL_PERKIRAAN, JUMLAH_PEKAN_PELATIHAN, JUMLAH_PERKIRAAN, BATAS_BAWAH, BATAS_ATAS, PENYESUAIAN_KALENDER, KETERANGAN)
    VALUES (s.ID_PERKIRAAN, s.ID_MODEL, s.AWAL_PEKAN_SASARAN, s.TANGGAL_PERKIRAAN, s.JUMLAH_PEKAN_PELATIHAN, s.JUMLAH_PERKIRAAN, s.BATAS_BAWAH, s.BATAS_ATAS, s.PENYESUAIAN_KALENDER, s.KETERANGAN);

-- =============================================================================
-- >>> sql/05_create_views.sql
-- =============================================================================

-- =============================================================================
-- Step 5: Create the ANALISIS summary views
--
-- Creates : the views of schema ANALISIS for the business use cases (see docs/USE_CASES.md).
-- Requires: steps 1-4 (tables and data). Views can be created before data is
--           loaded, but they will return no rows.
-- Safe to re-run: yes (CREATE OR REPLACE VIEW only touches the views, never the
--           data tables).
--
-- Design rules
--   * ANALISIS holds aggregated or operational summaries only. No view exposes
--     names, person or household identifiers, or birth years of parishioners.
--     sql/06_validate_data.sql checks this.
--   * Every view carries the column SUMBER_DATA so that the simulated nature of
--     the data travels with every result.
--   * No view ranks regions or communities. Donation views describe economic capacity and
--     the shape of the distribution (total, mean, median), never generosity or faith.
--   * Weeks start on Monday and are computed with plain date arithmetic, so the result does not
--     depend on a session setting. Years count as complete only when the snapshot date in
--     MASTER_DATA.INFO_DATASET has passed 31 December.
--   * Views are listed in dependency order: a view only reads views defined above it
--     (views 8 and 9 read view 7, view 10 reads view 9, view 12 reads view 11, view 23 reads view 7,
--     view 24 reads view 14, views 25 and 26 read view 24, views 28 and 29 read view 27).
--   * "Upcoming" is always relative to the snapshot date in MASTER_DATA.INFO_DATASET, never to the
--     clock, so the demo gives the same answer on any day. With real data, replace it by CURRENT_DATE.
-- =============================================================================

USE DATABASE PUSAT_INFORMASI_PAROKI;

-- 1. Region and community structure -------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.STRUKTUR_WILAYAH
    COMMENT = 'Struktur wilayah dan lingkungan beserta masa berlaku. Data simulasi.'
AS
SELECT
    w.ID_WILAYAH,
    w.NAMA_WILAYAH,
    l.ID_LINGKUNGAN,
    l.NAMA_LINGKUNGAN,
    l.STATUS_AKTIF AS LINGKUNGAN_AKTIF,
    l.TANGGAL_MULAI_BERLAKU,
    l.TANGGAL_AKHIR_BERLAKU,
    CASE WHEN g.ID_GEOMETRI IS NULL THEN FALSE ELSE TRUE END AS MEMILIKI_GEOMETRI_ILUSTRATIF,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM MASTER_DATA.MASTER_LINGKUNGAN l
JOIN MASTER_DATA.MASTER_WILAYAH w
    ON w.ID_WILAYAH = l.ID_WILAYAH
LEFT JOIN MASTER_DATA.GEOMETRI_ILUSTRATIF_LINGKUNGAN g
    ON g.ID_LINGKUNGAN = l.ID_LINGKUNGAN;

-- 2. Scheduled versus actual Mass times -----------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.PELAKSANAAN_MISA
    COMMENT = 'Satu baris per kejadian Misa: jadwal, waktu aktual, selisih menit, dan jumlah umat. Data simulasi.'
AS
SELECT
    k.ID_KEJADIAN_MISA,
    k.TANGGAL_MISA,
    p.ID_PERIODE_PELAPORAN,
    p.NAMA_PERIODE,
    j.NAMA_MISA,
    j.HARI,
    j.LOKASI,
    j.BAHASA_MISA,
    k.STATUS_PELAKSANAAN,
    j.WAKTU_MULAI AS WAKTU_MULAI_JADWAL,
    k.WAKTU_MULAI_AKTUAL,
    j.WAKTU_SELESAI AS WAKTU_SELESAI_JADWAL,
    k.WAKTU_SELESAI_AKTUAL,
    CASE WHEN k.WAKTU_MULAI_AKTUAL IS NULL THEN NULL ELSE
        (EXTRACT(HOUR FROM k.WAKTU_MULAI_AKTUAL) * 60 + EXTRACT(MINUTE FROM k.WAKTU_MULAI_AKTUAL))
        - (EXTRACT(HOUR FROM j.WAKTU_MULAI) * 60 + EXTRACT(MINUTE FROM j.WAKTU_MULAI))
    END AS SELISIH_MULAI_MENIT,
    CASE WHEN k.WAKTU_MULAI_AKTUAL IS NULL THEN NULL ELSE
        (EXTRACT(HOUR FROM k.WAKTU_SELESAI_AKTUAL) * 60 + EXTRACT(MINUTE FROM k.WAKTU_SELESAI_AKTUAL))
        - (EXTRACT(HOUR FROM k.WAKTU_MULAI_AKTUAL) * 60 + EXTRACT(MINUTE FROM k.WAKTU_MULAI_AKTUAL))
    END AS DURASI_AKTUAL_MENIT,
    a.JUMLAH_UMAT,
    a.STATUS_VALIDASI AS STATUS_VALIDASI_KEHADIRAN,
    k.KETERANGAN,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM DATA_OPERASIONAL.KEJADIAN_MISA k
JOIN MASTER_DATA.JADWAL_MISA j
    ON j.ID_JADWAL_MISA = k.ID_JADWAL_MISA
JOIN MASTER_DATA.REFERENSI_PERIODE_PELAPORAN p
    ON k.TANGGAL_MISA BETWEEN p.TANGGAL_MULAI AND p.TANGGAL_SELESAI
LEFT JOIN DATA_OPERASIONAL.KEHADIRAN_MISA a
    ON a.ID_KEJADIAN_MISA = k.ID_KEJADIAN_MISA;

-- 3. Monthly attendance by Mass session ---------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.KEHADIRAN_MISA_BULANAN
    COMMENT = 'Kehadiran umat per bulan dan sesi Misa (hanya Misa yang terlaksana). Data simulasi.'
AS
SELECT
    p.ID_PERIODE_PELAPORAN,
    p.TAHUN,
    p.BULAN,
    p.NAMA_PERIODE,
    j.NAMA_MISA,
    COUNT(*) AS JUMLAH_MISA_TERLAKSANA,
    SUM(a.JUMLAH_UMAT) AS TOTAL_UMAT,
    ROUND(AVG(a.JUMLAH_UMAT), 1) AS RATA_RATA_UMAT_PER_MISA,
    MIN(a.JUMLAH_UMAT) AS UMAT_TERENDAH,
    MAX(a.JUMLAH_UMAT) AS UMAT_TERTINGGI,
    SUM(CASE WHEN a.STATUS_VALIDASI = 'Sudah Divalidasi' THEN 1 ELSE 0 END) AS JUMLAH_SUDAH_DIVALIDASI,
    SUM(CASE WHEN a.STATUS_VALIDASI <> 'Sudah Divalidasi' THEN 1 ELSE 0 END) AS JUMLAH_BELUM_FINAL,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM DATA_OPERASIONAL.KEJADIAN_MISA k
JOIN DATA_OPERASIONAL.KEHADIRAN_MISA a
    ON a.ID_KEJADIAN_MISA = k.ID_KEJADIAN_MISA
JOIN MASTER_DATA.JADWAL_MISA j
    ON j.ID_JADWAL_MISA = k.ID_JADWAL_MISA
JOIN MASTER_DATA.REFERENSI_PERIODE_PELAPORAN p
    ON k.TANGGAL_MISA BETWEEN p.TANGGAL_MULAI AND p.TANGGAL_SELESAI
WHERE k.STATUS_PELAKSANAAN = 'Terlaksana'
GROUP BY p.ID_PERIODE_PELAPORAN, p.TAHUN, p.BULAN, p.NAMA_PERIODE, j.NAMA_MISA;

-- 4. Monthly offertory by Mass session and collection type ----------------------------------
CREATE OR REPLACE VIEW ANALISIS.KOLEKTE_MISA_BULANAN
    COMMENT = 'Kolekte per bulan, sesi Misa, dan jenis kolekte: jumlah tercatat, hasil penghitungan, dan status rekonsiliasi. Bukan ukuran iman. Data simulasi.'
AS
SELECT
    p.ID_PERIODE_PELAPORAN,
    p.TAHUN,
    p.BULAN,
    p.NAMA_PERIODE,
    j.NAMA_MISA,
    t.NAMA_JENIS_KOLEKTE,
    COUNT(*) AS JUMLAH_CATATAN,
    SUM(c.JUMLAH_PENERIMAAN) AS TOTAL_TERCATAT,
    SUM(c.JUMLAH_HASIL_PENGHITUNGAN) AS TOTAL_HASIL_PENGHITUNGAN,
    SUM(CASE WHEN c.JUMLAH_HASIL_PENGHITUNGAN IS NOT NULL THEN c.JUMLAH_PENERIMAAN ELSE 0 END) AS TOTAL_TERCATAT_YANG_SUDAH_DIHITUNG,
    SUM(CASE WHEN c.JUMLAH_HASIL_PENGHITUNGAN IS NOT NULL THEN c.JUMLAH_HASIL_PENGHITUNGAN - c.JUMLAH_PENERIMAAN ELSE 0 END) AS SELISIH_PADA_YANG_SUDAH_DIHITUNG,
    SUM(CASE WHEN c.STATUS_REKONSILIASI = 'Sudah Cocok' THEN 1 ELSE 0 END) AS JUMLAH_SUDAH_COCOK,
    SUM(CASE WHEN c.STATUS_REKONSILIASI IN ('Selisih Disetujui', 'Selisih Sedang Ditelusuri') THEN 1 ELSE 0 END) AS JUMLAH_ADA_SELISIH,
    SUM(CASE WHEN c.STATUS_REKONSILIASI = 'Belum Dihitung' THEN 1 ELSE 0 END) AS JUMLAH_BELUM_DIHITUNG,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM DATA_OPERASIONAL.PENERIMAAN_KOLEKTE c
JOIN DATA_OPERASIONAL.KEJADIAN_MISA k
    ON k.ID_KEJADIAN_MISA = c.ID_KEJADIAN_MISA
JOIN MASTER_DATA.JADWAL_MISA j
    ON j.ID_JADWAL_MISA = k.ID_JADWAL_MISA
JOIN MASTER_DATA.REFERENSI_JENIS_KOLEKTE t
    ON t.ID_JENIS_KOLEKTE = c.ID_JENIS_KOLEKTE
JOIN MASTER_DATA.REFERENSI_PERIODE_PELAPORAN p
    ON k.TANGGAL_MISA BETWEEN p.TANGGAL_MULAI AND p.TANGGAL_SELESAI
GROUP BY p.ID_PERIODE_PELAPORAN, p.TAHUN, p.BULAN, p.NAMA_PERIODE, j.NAMA_MISA, t.NAMA_JENIS_KOLEKTE;

-- 5. Attendance trend across reporting periods -----------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.TREN_KEHADIRAN_PERIODE
    COMMENT = 'Tren kehadiran seluruh Misa per bulan dengan perbandingan terhadap bulan sebelumnya. Data simulasi.'
AS
WITH BULANAN AS (
    SELECT
        p.ID_PERIODE_PELAPORAN,
        p.TAHUN,
        p.BULAN,
        p.NAMA_PERIODE,
        COUNT(*) AS JUMLAH_MISA_TERLAKSANA,
        SUM(a.JUMLAH_UMAT) AS TOTAL_UMAT,
        ROUND(AVG(a.JUMLAH_UMAT), 1) AS RATA_RATA_UMAT_PER_MISA
    FROM DATA_OPERASIONAL.KEJADIAN_MISA k
    JOIN DATA_OPERASIONAL.KEHADIRAN_MISA a
        ON a.ID_KEJADIAN_MISA = k.ID_KEJADIAN_MISA
    JOIN MASTER_DATA.REFERENSI_PERIODE_PELAPORAN p
        ON k.TANGGAL_MISA BETWEEN p.TANGGAL_MULAI AND p.TANGGAL_SELESAI
    WHERE k.STATUS_PELAKSANAAN = 'Terlaksana'
    GROUP BY p.ID_PERIODE_PELAPORAN, p.TAHUN, p.BULAN, p.NAMA_PERIODE
),
DENGAN_PEMBANDING AS (
    SELECT
        b.*,
        LAG(b.RATA_RATA_UMAT_PER_MISA) OVER (ORDER BY b.TAHUN, b.BULAN) AS RATA_RATA_BULAN_SEBELUMNYA
    FROM BULANAN b
)
SELECT
    ID_PERIODE_PELAPORAN,
    TAHUN,
    BULAN,
    NAMA_PERIODE,
    JUMLAH_MISA_TERLAKSANA,
    TOTAL_UMAT,
    RATA_RATA_UMAT_PER_MISA,
    RATA_RATA_BULAN_SEBELUMNYA,
    CASE WHEN RATA_RATA_BULAN_SEBELUMNYA IS NULL OR RATA_RATA_BULAN_SEBELUMNYA = 0 THEN NULL
         ELSE ROUND(100.0 * (RATA_RATA_UMAT_PER_MISA - RATA_RATA_BULAN_SEBELUMNYA) / RATA_RATA_BULAN_SEBELUMNYA, 1)
    END AS PERUBAHAN_PERSEN_RATA_RATA,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM DENGAN_PEMBANDING;

-- 6. Special occasion donations by region -------------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.SUMBANGAN_KHUSUS_PER_WILAYAH
    COMMENT = 'Sumbangan kampanye (Prapaskah, Adven, solidaritas) per wilayah. Hanya ringkasan, tidak untuk memeringkat wilayah. Data simulasi.'
AS
SELECT
    s.ID_SUMBANGAN,
    k.ID_KAMPANYE,
    k.NAMA_KAMPANYE,
    o.NAMA_KESEMPATAN,
    o.MUSIM_LITURGI,
    k.PERIODE_MULAI,
    k.PERIODE_SELESAI,
    w.ID_WILAYAH,
    w.NAMA_WILAYAH,
    s.JUMLAH_KELUARGA_PESERTA,
    s.JUMLAH_SUMBANGAN,
    SUM(s.JUMLAH_SUMBANGAN) OVER (PARTITION BY s.ID_KAMPANYE) AS TOTAL_SUMBANGAN_SELURUH_WILAYAH,
    s.TANGGAL_PENCATATAN,
    s.STATUS_VALIDASI,
    'Hanya untuk ringkasan, jangan dipakai untuk memeringkat wilayah.' AS CATATAN_PENGGUNAAN,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM DATA_OPERASIONAL.SUMBANGAN_KESEMPATAN_KHUSUS s
JOIN DATA_OPERASIONAL.KAMPANYE_SUMBANGAN k
    ON k.ID_KAMPANYE = s.ID_KAMPANYE
JOIN MASTER_DATA.MASTER_WILAYAH w
    ON w.ID_WILAYAH = s.ID_WILAYAH
JOIN MASTER_DATA.REFERENSI_KESEMPATAN_KHUSUS o
    ON o.ID_KESEMPATAN = k.ID_KESEMPATAN;

-- 7. Planned budget versus actual expenditure per program ----------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.ANGGARAN_VS_REALISASI_PROGRAM
    COMMENT = 'Anggaran rencana dibandingkan pengeluaran sebenarnya untuk setiap program. Data simulasi.'
AS
WITH ANGGARAN AS (
    SELECT ID_RENCANA, SUM(JUMLAH_ANGGARAN) AS TOTAL_ANGGARAN
    FROM DATA_OPERASIONAL.ALOKASI_ANGGARAN
    GROUP BY ID_RENCANA
),
REALISASI AS (
    SELECT a.ID_RENCANA, SUM(x.JUMLAH_PENGELUARAN) AS TOTAL_REALISASI
    FROM DATA_OPERASIONAL.REALISASI_PENGELUARAN x
    JOIN DATA_OPERASIONAL.ALOKASI_ANGGARAN a
        ON a.ID_ALOKASI = x.ID_ALOKASI
    GROUP BY a.ID_RENCANA
)
SELECT
    r.ID_RENCANA,
    h.TAHUN_RENCANA,
    s.ID_SEKSI,
    s.NAMA_SEKSI,
    r.NAMA_PROGRAM,
    r.TANGGAL_RENCANA,
    r.STATUS_PELAKSANAAN,
    COALESCE(a.TOTAL_ANGGARAN, 0) AS ANGGARAN_RENCANA,
    COALESCE(x.TOTAL_REALISASI, 0) AS ANGGARAN_TERPAKAI,
    COALESCE(a.TOTAL_ANGGARAN, 0) - COALESCE(x.TOTAL_REALISASI, 0) AS SISA_ANGGARAN,
    CASE WHEN COALESCE(a.TOTAL_ANGGARAN, 0) = 0 THEN NULL
         ELSE ROUND(100.0 * COALESCE(x.TOTAL_REALISASI, 0) / a.TOTAL_ANGGARAN, 1)
    END AS PERSEN_TERPAKAI,
    CASE WHEN COALESCE(x.TOTAL_REALISASI, 0) = 0 THEN 'Belum ada pengeluaran'
         WHEN x.TOTAL_REALISASI > a.TOTAL_ANGGARAN THEN 'Melebihi anggaran'
         WHEN x.TOTAL_REALISASI >= 0.95 * a.TOTAL_ANGGARAN THEN 'Hampir habis'
         ELSE 'Terpakai sebagian'
    END AS STATUS_PENYERAPAN,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM DATA_OPERASIONAL.RENCANA_KEGIATAN r
JOIN DATA_OPERASIONAL.RENCANA_KERJA_TAHUNAN h
    ON h.ID_RENCANA_KERJA = r.ID_RENCANA_KERJA
JOIN MASTER_DATA.MASTER_SEKSI s
    ON s.ID_SEKSI = h.ID_SEKSI
LEFT JOIN ANGGARAN a
    ON a.ID_RENCANA = r.ID_RENCANA
LEFT JOIN REALISASI x
    ON x.ID_RENCANA = r.ID_RENCANA;

-- 8. Planned budget versus actual expenditure per section ------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.ANGGARAN_VS_REALISASI_SEKSI
    COMMENT = 'Ringkasan anggaran dan pengeluaran per seksi, termasuk pembandingan khusus untuk program yang sudah terlaksana. Data simulasi.'
AS
SELECT
    ID_SEKSI,
    NAMA_SEKSI,
    TAHUN_RENCANA,
    COUNT(*) AS JUMLAH_PROGRAM,
    SUM(CASE WHEN STATUS_PELAKSANAAN = 'Terlaksana' THEN 1 ELSE 0 END) AS JUMLAH_TERLAKSANA,
    SUM(CASE WHEN STATUS_PELAKSANAAN = 'Direncanakan' THEN 1 ELSE 0 END) AS JUMLAH_DIRENCANAKAN,
    SUM(CASE WHEN STATUS_PELAKSANAAN = 'Ditunda' THEN 1 ELSE 0 END) AS JUMLAH_DITUNDA,
    SUM(CASE WHEN STATUS_PELAKSANAAN = 'Dibatalkan' THEN 1 ELSE 0 END) AS JUMLAH_DIBATALKAN,
    SUM(ANGGARAN_RENCANA) AS ANGGARAN_SEMUA_PROGRAM,
    SUM(ANGGARAN_TERPAKAI) AS ANGGARAN_TERPAKAI_SEMUA_PROGRAM,
    SUM(CASE WHEN STATUS_PELAKSANAAN = 'Terlaksana' THEN ANGGARAN_RENCANA ELSE 0 END) AS ANGGARAN_PROGRAM_TERLAKSANA,
    SUM(CASE WHEN STATUS_PELAKSANAAN = 'Terlaksana' THEN ANGGARAN_TERPAKAI ELSE 0 END) AS REALISASI_PROGRAM_TERLAKSANA,
    CASE WHEN SUM(CASE WHEN STATUS_PELAKSANAAN = 'Terlaksana' THEN ANGGARAN_RENCANA ELSE 0 END) = 0 THEN NULL
         ELSE ROUND(100.0 * SUM(CASE WHEN STATUS_PELAKSANAAN = 'Terlaksana' THEN ANGGARAN_TERPAKAI ELSE 0 END)
                    / SUM(CASE WHEN STATUS_PELAKSANAAN = 'Terlaksana' THEN ANGGARAN_RENCANA ELSE 0 END), 1)
    END AS PERSEN_TERPAKAI_PROGRAM_TERLAKSANA,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM ANALISIS.ANGGARAN_VS_REALISASI_PROGRAM
GROUP BY ID_SEKSI, NAMA_SEKSI, TAHUN_RENCANA;

-- 9. Events with their post-event report ----------------------------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.KEGIATAN_DAN_LAPORAN
    COMMENT = 'Setiap kegiatan dengan target peserta, peserta aktual, anggaran, dan status laporan pascakegiatan. Data simulasi.'
AS
SELECT
    e.ID_KEGIATAN,
    e.NAMA_KEGIATAN,
    s.NAMA_SEKSI,
    CASE WHEN e.ID_RENCANA IS NULL THEN 'Tidak direncanakan' ELSE 'Sesuai rencana kerja' END AS JENIS_KEGIATAN,
    e.TANGGAL_MULAI,
    e.TANGGAL_SELESAI,
    e.LOKASI,
    e.STATUS_KEGIATAN,
    e.TARGET_PESERTA,
    e.JUMLAH_PESERTA_AKTUAL,
    CASE WHEN e.JUMLAH_PESERTA_AKTUAL IS NULL OR e.TARGET_PESERTA = 0 THEN NULL
         ELSE ROUND(100.0 * e.JUMLAH_PESERTA_AKTUAL / e.TARGET_PESERTA, 1)
    END AS PERSEN_CAPAIAN_TARGET,
    b.ANGGARAN_RENCANA,
    b.ANGGARAN_TERPAKAI,
    r.ID_LAPORAN,
    CASE WHEN r.ID_LAPORAN IS NOT NULL THEN r.STATUS_LAPORAN
         WHEN e.STATUS_KEGIATAN = 'Terlaksana' THEN 'Belum ada laporan'
         ELSE 'Belum diperlukan'
    END AS STATUS_PELAPORAN,
    r.TANGGAL_LAPORAN,
    CASE WHEN r.ID_LAPORAN IS NULL THEN NULL
         WHEN r.RINGKASAN_PELAKSANAAN IS NOT NULL AND r.JUMLAH_PESERTA IS NOT NULL AND r.REALISASI_BIAYA IS NOT NULL
              AND r.EVALUASI_LOGISTIK IS NOT NULL AND r.HASIL_KEGIATAN IS NOT NULL
              AND r.REKOMENDASI_TINDAK_LANJUT IS NOT NULL THEN 'Isi lengkap'
         ELSE 'Isi belum lengkap'
    END AS KELENGKAPAN_ISI_LAPORAN,
    r.REALISASI_BIAYA AS BIAYA_MENURUT_LAPORAN,
    r.NAMA_BERKAS_SUMBER AS NAMA_BERKAS_LAPORAN,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM DATA_OPERASIONAL.KEGIATAN e
JOIN MASTER_DATA.MASTER_SEKSI s
    ON s.ID_SEKSI = e.ID_SEKSI
LEFT JOIN DATA_OPERASIONAL.LAPORAN_KEGIATAN r
    ON r.ID_KEGIATAN = e.ID_KEGIATAN
LEFT JOIN ANALISIS.ANGGARAN_VS_REALISASI_PROGRAM b
    ON b.ID_RENCANA = e.ID_RENCANA;

-- 10. Report completion per section ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.KELENGKAPAN_LAPORAN_PER_SEKSI
    COMMENT = 'Jumlah kegiatan per status dan kelengkapan laporan pascakegiatan untuk setiap seksi. Data simulasi.'
AS
SELECT
    NAMA_SEKSI,
    COUNT(*) AS JUMLAH_KEGIATAN,
    SUM(CASE WHEN STATUS_KEGIATAN = 'Terlaksana' THEN 1 ELSE 0 END) AS JUMLAH_TERLAKSANA,
    SUM(CASE WHEN STATUS_KEGIATAN = 'Direncanakan' THEN 1 ELSE 0 END) AS JUMLAH_DIRENCANAKAN,
    SUM(CASE WHEN STATUS_KEGIATAN = 'Ditunda' THEN 1 ELSE 0 END) AS JUMLAH_DITUNDA,
    SUM(CASE WHEN STATUS_KEGIATAN = 'Dibatalkan' THEN 1 ELSE 0 END) AS JUMLAH_DIBATALKAN,
    SUM(CASE WHEN STATUS_PELAPORAN = 'Final' THEN 1 ELSE 0 END) AS JUMLAH_LAPORAN_FINAL,
    SUM(CASE WHEN STATUS_PELAPORAN IN ('Draf', 'Perlu Revisi') THEN 1 ELSE 0 END) AS JUMLAH_LAPORAN_DRAF_ATAU_REVISI,
    SUM(CASE WHEN STATUS_PELAPORAN = 'Belum ada laporan' THEN 1 ELSE 0 END) AS JUMLAH_BELUM_ADA_LAPORAN,
    CASE WHEN SUM(CASE WHEN STATUS_KEGIATAN = 'Terlaksana' THEN 1 ELSE 0 END) = 0 THEN NULL
         ELSE ROUND(100.0 * SUM(CASE WHEN STATUS_PELAPORAN = 'Final' THEN 1 ELSE 0 END)
                    / SUM(CASE WHEN STATUS_KEGIATAN = 'Terlaksana' THEN 1 ELSE 0 END), 1)
    END AS PERSEN_TERLAKSANA_DENGAN_LAPORAN_FINAL,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM ANALISIS.KEGIATAN_DAN_LAPORAN
GROUP BY NAMA_SEKSI;

-- 11. Aggregated survey findings ---------------------------------------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.HASIL_SURVEI
    COMMENT = 'Hasil survei yang sudah dirangkum: jumlah dan persentase responden per kategori jawaban. Data simulasi.'
AS
SELECT
    sv.ID_SURVEI,
    sv.JUDUL_SURVEI,
    sv.STATUS_SURVEI,
    q.ID_PERTANYAAN,
    q.NOMOR_URUT AS NOMOR_PERTANYAAN,
    q.TEKS_PERTANYAAN,
    q.JENIS_JAWABAN,
    o.NOMOR_URUT AS NOMOR_OPSI,
    o.KATEGORI_JAWABAN,
    o.NILAI_SKOR,
    h.JUMLAH_RESPONDEN,
    h.TOTAL_RESPONDEN_PERTANYAAN,
    h.PERSENTASE_JAWABAN,
    h.TANGGAL_AGREGASI,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM DATA_OPERASIONAL.HASIL_SURVEI_AGREGAT h
JOIN MASTER_DATA.SURVEI sv
    ON sv.ID_SURVEI = h.ID_SURVEI
JOIN MASTER_DATA.PERTANYAAN_SURVEI q
    ON q.ID_PERTANYAAN = h.ID_PERTANYAAN
JOIN MASTER_DATA.OPSI_JAWABAN_SURVEI o
    ON o.ID_OPSI = h.ID_OPSI;

-- 12. Likert score summary --------------------------------------------------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.RINGKASAN_SKOR_LIKERT
    COMMENT = 'Skor rata-rata (1 sampai 5) dan persentase setuju untuk pertanyaan berskala Likert. Data simulasi.'
AS
SELECT
    ID_SURVEI,
    JUDUL_SURVEI,
    ID_PERTANYAAN,
    NOMOR_PERTANYAAN,
    TEKS_PERTANYAAN,
    MAX(TOTAL_RESPONDEN_PERTANYAAN) AS JUMLAH_RESPONDEN,
    CASE WHEN MAX(TOTAL_RESPONDEN_PERTANYAAN) = 0 THEN NULL
         ELSE ROUND(1.0 * SUM(NILAI_SKOR * JUMLAH_RESPONDEN) / MAX(TOTAL_RESPONDEN_PERTANYAAN), 2)
    END AS SKOR_RATA_RATA,
    SUM(CASE WHEN NILAI_SKOR >= 4 THEN PERSENTASE_JAWABAN ELSE 0 END) AS PERSEN_SETUJU_ATAU_SANGAT_SETUJU,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM ANALISIS.HASIL_SURVEI
WHERE JENIS_JAWABAN = 'Skala Likert'
GROUP BY ID_SURVEI, JUDUL_SURVEI, ID_PERTANYAAN, NOMOR_PERTANYAAN, TEKS_PERTANYAAN;

-- 13. Parishioner counts per community (aggregates only) --------------------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.RINGKASAN_UMAT_PER_LINGKUNGAN
    COMMENT = 'Jumlah keluarga dan umat aktif per lingkungan. Hanya angka agregat, tanpa nama atau identitas individu. Data simulasi.'
AS
SELECT
    w.ID_WILAYAH,
    w.NAMA_WILAYAH,
    l.ID_LINGKUNGAN,
    l.NAMA_LINGKUNGAN,
    COUNT(DISTINCT pl.ID_KELUARGA) AS JUMLAH_KELUARGA_AKTIF,
    COUNT(DISTINCT u.ID_UMAT) AS JUMLAH_UMAT_AKTIF,
    'Hanya angka agregat, tanpa data pribadi.' AS CATATAN_PRIVASI,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM MASTER_DATA.MASTER_LINGKUNGAN l
JOIN MASTER_DATA.MASTER_WILAYAH w
    ON w.ID_WILAYAH = l.ID_WILAYAH
LEFT JOIN DATA_OPERASIONAL.PENUGASAN_LINGKUNGAN pl
    ON pl.ID_LINGKUNGAN = l.ID_LINGKUNGAN
   AND pl.TANGGAL_AKHIR_BERLAKU IS NULL
LEFT JOIN DATA_OPERASIONAL.PENUGASAN_KELUARGA pk
    ON pk.ID_KELUARGA = pl.ID_KELUARGA
   AND pk.TANGGAL_AKHIR_BERLAKU IS NULL
LEFT JOIN DATA_OPERASIONAL.UMAT u
    ON u.ID_UMAT = pk.ID_UMAT
   AND u.STATUS_KEANGGOTAAN = 'Aktif'
WHERE l.STATUS_AKTIF = TRUE
GROUP BY w.ID_WILAYAH, w.NAMA_WILAYAH, l.ID_LINGKUNGAN, l.NAMA_LINGKUNGAN;

-- =============================================================================
-- Use case views: income versus outcome, unforeseen events, economic mapping, break-even
-- =============================================================================

-- 14. Weekly offertory and attendance, annotated with unforeseen events --------------------------------
CREATE OR REPLACE VIEW ANALISIS.KOLEKTE_MINGGUAN_DAN_PERISTIWA
    COMMENT = 'Kolekte dan kehadiran per pekan (Senin sampai Minggu) dengan peristiwa luar biasa, untuk grafik riwayat dan membaca penyimpangan peramalan. Data simulasi.'
AS
WITH KOLEKTE_PER_MISA AS (
    SELECT ID_KEJADIAN_MISA,
           SUM(COALESCE(JUMLAH_HASIL_PENGHITUNGAN, JUMLAH_PENERIMAAN)) AS TOTAL_KOLEKTE
    FROM DATA_OPERASIONAL.PENERIMAAN_KOLEKTE
    GROUP BY ID_KEJADIAN_MISA
),
PEKANAN AS (
    SELECT
        DATEADD('day', -MOD(DATEDIFF('day', DATE '1900-01-01', k.TANGGAL_MISA), 7), k.TANGGAL_MISA) AS AWAL_PEKAN,
        COUNT(*) AS JUMLAH_MISA_TERLAKSANA,
        SUM(a.JUMLAH_UMAT) AS TOTAL_UMAT,
        SUM(c.TOTAL_KOLEKTE) AS TOTAL_KOLEKTE,
        MIN(a.ID_PERISTIWA) AS ID_PERISTIWA
    FROM DATA_OPERASIONAL.KEJADIAN_MISA k
    JOIN DATA_OPERASIONAL.KEHADIRAN_MISA a
        ON a.ID_KEJADIAN_MISA = k.ID_KEJADIAN_MISA
    JOIN KOLEKTE_PER_MISA c
        ON c.ID_KEJADIAN_MISA = k.ID_KEJADIAN_MISA
    WHERE k.STATUS_PELAKSANAAN = 'Terlaksana'
    GROUP BY DATEADD('day', -MOD(DATEDIFF('day', DATE '1900-01-01', k.TANGGAL_MISA), 7), k.TANGGAL_MISA)
),
DENGAN_PEMBANDING AS (
    SELECT
        w.AWAL_PEKAN,
        w.JUMLAH_MISA_TERLAKSANA,
        w.TOTAL_UMAT,
        w.TOTAL_KOLEKTE,
        w.ID_PERISTIWA,
        AVG(w.TOTAL_UMAT) OVER (ORDER BY w.AWAL_PEKAN ROWS BETWEEN 8 PRECEDING AND 1 PRECEDING) AS RATA_RATA_UMAT_8_PEKAN_SEBELUMNYA,
        AVG(w.TOTAL_KOLEKTE) OVER (ORDER BY w.AWAL_PEKAN ROWS BETWEEN 8 PRECEDING AND 1 PRECEDING) AS RATA_RATA_KOLEKTE_8_PEKAN_SEBELUMNYA
    FROM PEKANAN w
)
SELECT
    d.AWAL_PEKAN,
    EXTRACT(YEAR FROM d.AWAL_PEKAN) AS TAHUN,
    d.JUMLAH_MISA_TERLAKSANA,
    d.TOTAL_UMAT,
    d.TOTAL_KOLEKTE,
    d.RATA_RATA_UMAT_8_PEKAN_SEBELUMNYA,
    d.RATA_RATA_KOLEKTE_8_PEKAN_SEBELUMNYA,
    CASE WHEN d.RATA_RATA_UMAT_8_PEKAN_SEBELUMNYA IS NULL OR d.RATA_RATA_UMAT_8_PEKAN_SEBELUMNYA = 0 THEN NULL
         ELSE ROUND(100.0 * d.TOTAL_UMAT / d.RATA_RATA_UMAT_8_PEKAN_SEBELUMNYA, 1)
    END AS PERSEN_UMAT_TERHADAP_8_PEKAN_SEBELUMNYA,
    CASE WHEN d.RATA_RATA_KOLEKTE_8_PEKAN_SEBELUMNYA IS NULL OR d.RATA_RATA_KOLEKTE_8_PEKAN_SEBELUMNYA = 0 THEN NULL
         ELSE ROUND(100.0 * d.TOTAL_KOLEKTE / d.RATA_RATA_KOLEKTE_8_PEKAN_SEBELUMNYA, 1)
    END AS PERSEN_KOLEKTE_TERHADAP_8_PEKAN_SEBELUMNYA,
    e.ID_PERISTIWA,
    e.JENIS_PERISTIWA,
    e.NAMA_PERISTIWA,
    e.TINGKAT_GANGGUAN,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM DENGAN_PEMBANDING d
LEFT JOIN DATA_OPERASIONAL.PERISTIWA_LUAR_BIASA e
    ON e.ID_PERISTIWA = d.ID_PERISTIWA;

-- 15. Effect of each unforeseen event ---------------------------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.DAMPAK_PERISTIWA_LUAR_BIASA
    COMMENT = 'Kehadiran dan kolekte selama setiap peristiwa luar biasa dibandingkan dengan yang diharapkan dari rata-rata 8 pekan sebelumnya untuk sesi Misa yang sama. Data simulasi.'
AS
WITH KOLEKTE_PER_MISA AS (
    SELECT ID_KEJADIAN_MISA,
           SUM(COALESCE(JUMLAH_HASIL_PENGHITUNGAN, JUMLAH_PENERIMAAN)) AS TOTAL_KOLEKTE
    FROM DATA_OPERASIONAL.PENERIMAAN_KOLEKTE
    GROUP BY ID_KEJADIAN_MISA
),
MISA AS (
    SELECT k.TANGGAL_MISA, k.STATUS_PELAKSANAAN, j.NAMA_MISA, a.JUMLAH_UMAT, c.TOTAL_KOLEKTE
    FROM DATA_OPERASIONAL.KEJADIAN_MISA k
    JOIN MASTER_DATA.JADWAL_MISA j
        ON j.ID_JADWAL_MISA = k.ID_JADWAL_MISA
    LEFT JOIN DATA_OPERASIONAL.KEHADIRAN_MISA a
        ON a.ID_KEJADIAN_MISA = k.ID_KEJADIAN_MISA
    LEFT JOIN KOLEKTE_PER_MISA c
        ON c.ID_KEJADIAN_MISA = k.ID_KEJADIAN_MISA
    WHERE k.STATUS_PELAKSANAAN IN ('Terlaksana', 'Dibatalkan')
),
BASIS AS (
    -- what a Mass of each session normally brings in the 8 weeks before the event
    SELECT e.ID_PERISTIWA, m.NAMA_MISA,
           AVG(m.JUMLAH_UMAT) AS RATA_RATA_UMAT,
           AVG(m.TOTAL_KOLEKTE) AS RATA_RATA_KOLEKTE
    FROM DATA_OPERASIONAL.PERISTIWA_LUAR_BIASA e
    JOIN MISA m
        ON m.TANGGAL_MISA BETWEEN DATEADD('day', -56, e.TANGGAL_MULAI) AND DATEADD('day', -1, e.TANGGAL_MULAI)
    GROUP BY e.ID_PERISTIWA, m.NAMA_MISA
),
SELAMA AS (
    -- every scheduled Mass inside the event, compared with the normal result of its own session
    SELECT e.ID_PERISTIWA,
           SUM(CASE WHEN m.STATUS_PELAKSANAAN = 'Terlaksana' THEN 1 ELSE 0 END) AS JUMLAH_MISA_TERLAKSANA,
           SUM(CASE WHEN m.STATUS_PELAKSANAAN = 'Dibatalkan' THEN 1 ELSE 0 END) AS JUMLAH_MISA_DIBATALKAN,
           SUM(COALESCE(m.JUMLAH_UMAT, 0)) AS UMAT_AKTUAL,
           SUM(b.RATA_RATA_UMAT) AS UMAT_DIHARAPKAN,
           SUM(COALESCE(m.TOTAL_KOLEKTE, 0)) AS KOLEKTE_AKTUAL,
           SUM(b.RATA_RATA_KOLEKTE) AS KOLEKTE_DIHARAPKAN
    FROM DATA_OPERASIONAL.PERISTIWA_LUAR_BIASA e
    JOIN MISA m
        ON m.TANGGAL_MISA BETWEEN e.TANGGAL_MULAI AND e.TANGGAL_SELESAI
    LEFT JOIN BASIS b
        ON b.ID_PERISTIWA = e.ID_PERISTIWA AND b.NAMA_MISA = m.NAMA_MISA
    GROUP BY e.ID_PERISTIWA
)
SELECT
    e.ID_PERISTIWA,
    e.JENIS_PERISTIWA,
    e.NAMA_PERISTIWA,
    e.TANGGAL_MULAI,
    e.TANGGAL_SELESAI,
    e.TINGKAT_GANGGUAN,
    e.DESKRIPSI,
    d.JUMLAH_MISA_TERLAKSANA,
    d.JUMLAH_MISA_DIBATALKAN,
    d.UMAT_AKTUAL AS UMAT_AKTUAL_SELAMA_PERISTIWA,
    ROUND(d.UMAT_DIHARAPKAN, 0) AS UMAT_DIHARAPKAN,
    ROUND(100.0 * d.UMAT_AKTUAL / NULLIF(d.UMAT_DIHARAPKAN, 0), 1) AS PERSEN_KEHADIRAN_TERHADAP_HARAPAN,
    d.KOLEKTE_AKTUAL AS KOLEKTE_AKTUAL_SELAMA_PERISTIWA,
    ROUND(d.KOLEKTE_DIHARAPKAN, 0) AS KOLEKTE_DIHARAPKAN,
    ROUND(100.0 * d.KOLEKTE_AKTUAL / NULLIF(d.KOLEKTE_DIHARAPKAN, 0), 1) AS PERSEN_KOLEKTE_TERHADAP_HARAPAN,
    ROUND(d.KOLEKTE_DIHARAPKAN - d.KOLEKTE_AKTUAL, 0) AS PERKIRAAN_KOLEKTE_YANG_TIDAK_DITERIMA,
    'Pembanding kasar: rata-rata 8 pekan sebelumnya untuk sesi Misa yang sama, tanpa koreksi hari gajian dan musim.' AS CATATAN_METODE,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM DATA_OPERASIONAL.PERISTIWA_LUAR_BIASA e
LEFT JOIN SELAMA d
    ON d.ID_PERISTIWA = e.ID_PERISTIWA;

-- 16. Offertory pattern within the month (after salary day) -------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.POLA_KOLEKTE_HARI_DALAM_BULAN
    COMMENT = 'Kolekte per umat yang hadir menurut tanggal dalam bulan, per tahun. Pola administrasi (setelah hari gajian), bukan ukuran iman. Data simulasi.'
AS
WITH KOLEKTE_PER_MISA AS (
    SELECT ID_KEJADIAN_MISA,
           SUM(COALESCE(JUMLAH_HASIL_PENGHITUNGAN, JUMLAH_PENERIMAAN)) AS TOTAL_KOLEKTE
    FROM DATA_OPERASIONAL.PENERIMAAN_KOLEKTE
    GROUP BY ID_KEJADIAN_MISA
)
SELECT
    EXTRACT(YEAR FROM k.TANGGAL_MISA) AS TAHUN,
    EXTRACT(DAY FROM k.TANGGAL_MISA) AS HARI_DALAM_BULAN,
    CASE WHEN EXTRACT(DAY FROM k.TANGGAL_MISA) <= 7 THEN 'Tanggal 1-7'
         WHEN EXTRACT(DAY FROM k.TANGGAL_MISA) <= 14 THEN 'Tanggal 8-14'
         WHEN EXTRACT(DAY FROM k.TANGGAL_MISA) <= 21 THEN 'Tanggal 15-21'
         ELSE 'Tanggal 22-31'
    END AS KELOMPOK_TANGGAL,
    COUNT(*) AS JUMLAH_MISA,
    SUM(a.JUMLAH_UMAT) AS TOTAL_UMAT,
    SUM(c.TOTAL_KOLEKTE) AS TOTAL_KOLEKTE,
    ROUND(1.0 * SUM(c.TOTAL_KOLEKTE) / NULLIF(SUM(a.JUMLAH_UMAT), 0), 0) AS KOLEKTE_PER_UMAT,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM DATA_OPERASIONAL.KEJADIAN_MISA k
JOIN DATA_OPERASIONAL.KEHADIRAN_MISA a
    ON a.ID_KEJADIAN_MISA = k.ID_KEJADIAN_MISA
JOIN KOLEKTE_PER_MISA c
    ON c.ID_KEJADIAN_MISA = k.ID_KEJADIAN_MISA
WHERE k.STATUS_PELAKSANAAN = 'Terlaksana'
GROUP BY EXTRACT(YEAR FROM k.TANGGAL_MISA), EXTRACT(DAY FROM k.TANGGAL_MISA);

-- 17. Correlation of offertory with attendance and with the day of the month -----------------------------------------
CREATE OR REPLACE VIEW ANALISIS.KORELASI_KOLEKTE_KEHADIRAN
    COMMENT = 'Korelasi kolekte dengan jumlah umat dan dengan tanggal dalam bulan, per tahun dan sesi Misa. Data simulasi.'
AS
WITH KOLEKTE_PER_MISA AS (
    SELECT ID_KEJADIAN_MISA,
           SUM(COALESCE(JUMLAH_HASIL_PENGHITUNGAN, JUMLAH_PENERIMAAN)) AS TOTAL_KOLEKTE
    FROM DATA_OPERASIONAL.PENERIMAAN_KOLEKTE
    GROUP BY ID_KEJADIAN_MISA
)
SELECT
    EXTRACT(YEAR FROM k.TANGGAL_MISA) AS TAHUN,
    j.NAMA_MISA,
    COUNT(*) AS JUMLAH_MISA,
    ROUND(CORR(a.JUMLAH_UMAT, c.TOTAL_KOLEKTE), 3) AS KORELASI_KOLEKTE_DENGAN_UMAT,
    ROUND(REGR_R2(c.TOTAL_KOLEKTE, a.JUMLAH_UMAT), 3) AS R_KUADRAT_KOLEKTE_DARI_UMAT,
    ROUND(REGR_SLOPE(c.TOTAL_KOLEKTE, a.JUMLAH_UMAT), 0) AS TAMBAHAN_KOLEKTE_PER_UMAT,
    ROUND(CORR(EXTRACT(DAY FROM k.TANGGAL_MISA), 1.0 * c.TOTAL_KOLEKTE / a.JUMLAH_UMAT), 3) AS KORELASI_TANGGAL_DENGAN_KOLEKTE_PER_UMAT,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM DATA_OPERASIONAL.KEJADIAN_MISA k
JOIN DATA_OPERASIONAL.KEHADIRAN_MISA a
    ON a.ID_KEJADIAN_MISA = k.ID_KEJADIAN_MISA
JOIN KOLEKTE_PER_MISA c
    ON c.ID_KEJADIAN_MISA = k.ID_KEJADIAN_MISA
JOIN MASTER_DATA.JADWAL_MISA j
    ON j.ID_JADWAL_MISA = k.ID_JADWAL_MISA
WHERE k.STATUS_PELAKSANAAN = 'Terlaksana'
GROUP BY EXTRACT(YEAR FROM k.TANGGAL_MISA), j.NAMA_MISA;

-- 18. Income versus outcome per month ------------------------------------------------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.PEMASUKAN_PENGELUARAN_BULANAN
    COMMENT = 'Pemasukan (kolekte, sumbangan khusus) dan pengeluaran program per bulan, dengan peristiwa luar biasa. Data simulasi.'
AS
WITH KOLEKTE AS (
    SELECT p.ID_PERIODE_PELAPORAN,
           SUM(COALESCE(c.JUMLAH_HASIL_PENGHITUNGAN, c.JUMLAH_PENERIMAAN)) AS NILAI
    FROM DATA_OPERASIONAL.PENERIMAAN_KOLEKTE c
    JOIN DATA_OPERASIONAL.KEJADIAN_MISA k
        ON k.ID_KEJADIAN_MISA = c.ID_KEJADIAN_MISA
    JOIN MASTER_DATA.REFERENSI_PERIODE_PELAPORAN p
        ON k.TANGGAL_MISA BETWEEN p.TANGGAL_MULAI AND p.TANGGAL_SELESAI
    GROUP BY p.ID_PERIODE_PELAPORAN
),
SUMBANGAN AS (
    SELECT p.ID_PERIODE_PELAPORAN, SUM(g.JUMLAH_SUMBANGAN) AS NILAI
    FROM DATA_OPERASIONAL.SUMBANGAN_KELUARGA g
    JOIN MASTER_DATA.REFERENSI_PERIODE_PELAPORAN p
        ON g.TANGGAL_SUMBANGAN BETWEEN p.TANGGAL_MULAI AND p.TANGGAL_SELESAI
    GROUP BY p.ID_PERIODE_PELAPORAN
),
PENGELUARAN AS (
    SELECT p.ID_PERIODE_PELAPORAN, SUM(x.JUMLAH_PENGELUARAN) AS NILAI
    FROM DATA_OPERASIONAL.REALISASI_PENGELUARAN x
    JOIN MASTER_DATA.REFERENSI_PERIODE_PELAPORAN p
        ON x.TANGGAL_PENGELUARAN BETWEEN p.TANGGAL_MULAI AND p.TANGGAL_SELESAI
    GROUP BY p.ID_PERIODE_PELAPORAN
),
PERISTIWA AS (
    SELECT p.ID_PERIODE_PELAPORAN,
           MIN(e.NAMA_PERISTIWA) AS NAMA_PERISTIWA,
           MIN(e.JENIS_PERISTIWA) AS JENIS_PERISTIWA,
           MIN(e.TINGKAT_GANGGUAN) AS TINGKAT_GANGGUAN
    FROM MASTER_DATA.REFERENSI_PERIODE_PELAPORAN p
    JOIN DATA_OPERASIONAL.PERISTIWA_LUAR_BIASA e
        ON e.TANGGAL_MULAI <= p.TANGGAL_SELESAI AND e.TANGGAL_SELESAI >= p.TANGGAL_MULAI
    GROUP BY p.ID_PERIODE_PELAPORAN
)
SELECT
    p.ID_PERIODE_PELAPORAN,
    p.TAHUN,
    p.BULAN,
    p.NAMA_PERIODE,
    CASE WHEN p.TANGGAL_SELESAI <= i.TANGGAL_SNAPSHOT THEN 'Lengkap' ELSE 'Berjalan' END AS STATUS_PERIODE,
    COALESCE(k.NILAI, 0) AS PEMASUKAN_KOLEKTE,
    COALESCE(s.NILAI, 0) AS PEMASUKAN_SUMBANGAN_KHUSUS,
    COALESCE(k.NILAI, 0) + COALESCE(s.NILAI, 0) AS TOTAL_PEMASUKAN,
    COALESCE(x.NILAI, 0) AS PENGELUARAN_PROGRAM,
    COALESCE(k.NILAI, 0) - COALESCE(x.NILAI, 0) AS SELISIH_KOLEKTE_VS_PENGELUARAN,
    COALESCE(k.NILAI, 0) + COALESCE(s.NILAI, 0) - COALESCE(x.NILAI, 0) AS SELISIH_TOTAL,
    e.NAMA_PERISTIWA,
    e.JENIS_PERISTIWA,
    e.TINGKAT_GANGGUAN,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM MASTER_DATA.REFERENSI_PERIODE_PELAPORAN p
CROSS JOIN MASTER_DATA.INFO_DATASET i
LEFT JOIN KOLEKTE k ON k.ID_PERIODE_PELAPORAN = p.ID_PERIODE_PELAPORAN
LEFT JOIN SUMBANGAN s ON s.ID_PERIODE_PELAPORAN = p.ID_PERIODE_PELAPORAN
LEFT JOIN PENGELUARAN x ON x.ID_PERIODE_PELAPORAN = p.ID_PERIODE_PELAPORAN
LEFT JOIN PERISTIWA e ON e.ID_PERIODE_PELAPORAN = p.ID_PERIODE_PELAPORAN
WHERE p.TANGGAL_MULAI >= i.TANGGAL_MULAI_RIWAYAT
  AND p.TANGGAL_MULAI <= i.TANGGAL_SNAPSHOT;

-- 19. Income versus outcome per year ---------------------------------------------------------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.PEMASUKAN_PENGELUARAN_TAHUNAN
    COMMENT = 'Pemasukan dan pengeluaran program per tahun, pertumbuhan tahun ke tahun, dan kolekte per Misa tanpa peristiwa luar biasa. Tahun berjalan ditandai belum lengkap. Data simulasi.'
AS
WITH TAHUNAN AS (
    SELECT
        TAHUN,
        COUNT(*) AS JUMLAH_BULAN_TERCATAT,
        SUM(CASE WHEN STATUS_PERIODE = 'Lengkap' THEN 1 ELSE 0 END) AS JUMLAH_BULAN_LENGKAP,
        SUM(PEMASUKAN_KOLEKTE) AS PEMASUKAN_KOLEKTE,
        SUM(PEMASUKAN_SUMBANGAN_KHUSUS) AS PEMASUKAN_SUMBANGAN_KHUSUS,
        SUM(TOTAL_PEMASUKAN) AS TOTAL_PEMASUKAN,
        SUM(PENGELUARAN_PROGRAM) AS PENGELUARAN_PROGRAM
    FROM ANALISIS.PEMASUKAN_PENGELUARAN_BULANAN
    GROUP BY TAHUN
),
KOLEKTE_PER_MISA AS (
    SELECT ID_KEJADIAN_MISA,
           SUM(COALESCE(JUMLAH_HASIL_PENGHITUNGAN, JUMLAH_PENERIMAAN)) AS TOTAL_KOLEKTE
    FROM DATA_OPERASIONAL.PENERIMAAN_KOLEKTE
    GROUP BY ID_KEJADIAN_MISA
),
MISA AS (
    SELECT
        EXTRACT(YEAR FROM k.TANGGAL_MISA) AS TAHUN,
        COUNT(*) AS JUMLAH_MISA_TERLAKSANA,
        AVG(c.TOTAL_KOLEKTE) AS KOLEKTE_RATA_RATA_PER_MISA,
        AVG(CASE WHEN a.ID_PERISTIWA IS NULL THEN c.TOTAL_KOLEKTE END) AS KOLEKTE_RATA_RATA_PER_MISA_TANPA_PERISTIWA
    FROM DATA_OPERASIONAL.KEJADIAN_MISA k
    JOIN DATA_OPERASIONAL.KEHADIRAN_MISA a
        ON a.ID_KEJADIAN_MISA = k.ID_KEJADIAN_MISA
    JOIN KOLEKTE_PER_MISA c
        ON c.ID_KEJADIAN_MISA = k.ID_KEJADIAN_MISA
    WHERE k.STATUS_PELAKSANAAN = 'Terlaksana'
    GROUP BY EXTRACT(YEAR FROM k.TANGGAL_MISA)
),
PROGRAM AS (
    SELECT TAHUN_RENCANA AS TAHUN,
           SUM(CASE WHEN STATUS_PELAKSANAAN = 'Terlaksana' THEN 1 ELSE 0 END) AS JUMLAH_KEGIATAN_TERLAKSANA,
           SUM(CASE WHEN STATUS_PELAKSANAAN <> 'Dibatalkan' THEN ANGGARAN_RENCANA ELSE 0 END) AS ANGGARAN_PROGRAM
    FROM ANALISIS.ANGGARAN_VS_REALISASI_PROGRAM
    GROUP BY TAHUN_RENCANA
),
GABUNG AS (
    SELECT
        t.TAHUN,
        t.JUMLAH_BULAN_TERCATAT,
        CASE WHEN t.JUMLAH_BULAN_LENGKAP = 12 THEN TRUE ELSE FALSE END AS TAHUN_LENGKAP,
        t.PEMASUKAN_KOLEKTE,
        t.PEMASUKAN_SUMBANGAN_KHUSUS,
        t.TOTAL_PEMASUKAN,
        t.PENGELUARAN_PROGRAM,
        p.ANGGARAN_PROGRAM,
        p.JUMLAH_KEGIATAN_TERLAKSANA,
        m.JUMLAH_MISA_TERLAKSANA,
        ROUND(m.KOLEKTE_RATA_RATA_PER_MISA, 0) AS KOLEKTE_RATA_RATA_PER_MISA,
        ROUND(m.KOLEKTE_RATA_RATA_PER_MISA_TANPA_PERISTIWA, 0) AS KOLEKTE_RATA_RATA_PER_MISA_TANPA_PERISTIWA
    FROM TAHUNAN t
    LEFT JOIN PROGRAM p ON p.TAHUN = t.TAHUN
    LEFT JOIN MISA m ON m.TAHUN = t.TAHUN
),
DENGAN_PEMBANDING AS (
    SELECT
        g.*,
        LAG(g.PEMASUKAN_KOLEKTE) OVER (ORDER BY g.TAHUN) AS KOLEKTE_TAHUN_SEBELUMNYA,
        LAG(g.PENGELUARAN_PROGRAM) OVER (ORDER BY g.TAHUN) AS PENGELUARAN_TAHUN_SEBELUMNYA,
        LAG(g.KOLEKTE_RATA_RATA_PER_MISA_TANPA_PERISTIWA) OVER (ORDER BY g.TAHUN) AS KOLEKTE_PER_MISA_TANPA_PERISTIWA_SEBELUMNYA,
        LAG(g.TAHUN_LENGKAP) OVER (ORDER BY g.TAHUN) AS TAHUN_SEBELUMNYA_LENGKAP
    FROM GABUNG g
)
SELECT
    TAHUN,
    CASE WHEN TAHUN_LENGKAP THEN 'Tahun lengkap'
         ELSE 'Tahun berjalan (' || CAST(JUMLAH_BULAN_TERCATAT AS VARCHAR) || ' bulan pertama)' END AS STATUS_TAHUN,
    TAHUN_LENGKAP,
    JUMLAH_MISA_TERLAKSANA,
    PEMASUKAN_KOLEKTE,
    PEMASUKAN_SUMBANGAN_KHUSUS,
    TOTAL_PEMASUKAN,
    PENGELUARAN_PROGRAM,
    ANGGARAN_PROGRAM,
    JUMLAH_KEGIATAN_TERLAKSANA,
    PEMASUKAN_KOLEKTE - PENGELUARAN_PROGRAM AS SELISIH_KOLEKTE_VS_PENGELUARAN,
    TOTAL_PEMASUKAN - PENGELUARAN_PROGRAM AS SELISIH_TOTAL,
    ROUND(100.0 * PENGELUARAN_PROGRAM / NULLIF(PEMASUKAN_KOLEKTE, 0), 1) AS PERSEN_PENGELUARAN_TERHADAP_KOLEKTE,
    CASE WHEN TAHUN_LENGKAP AND TAHUN_SEBELUMNYA_LENGKAP AND KOLEKTE_TAHUN_SEBELUMNYA > 0
         THEN ROUND(100.0 * (PEMASUKAN_KOLEKTE - KOLEKTE_TAHUN_SEBELUMNYA) / KOLEKTE_TAHUN_SEBELUMNYA, 1) END AS PERTUMBUHAN_KOLEKTE_PERSEN,
    CASE WHEN TAHUN_LENGKAP AND TAHUN_SEBELUMNYA_LENGKAP AND PENGELUARAN_TAHUN_SEBELUMNYA > 0
         THEN ROUND(100.0 * (PENGELUARAN_PROGRAM - PENGELUARAN_TAHUN_SEBELUMNYA) / PENGELUARAN_TAHUN_SEBELUMNYA, 1) END AS PERTUMBUHAN_PENGELUARAN_PERSEN,
    KOLEKTE_RATA_RATA_PER_MISA,
    KOLEKTE_RATA_RATA_PER_MISA_TANPA_PERISTIWA,
    CASE WHEN KOLEKTE_PER_MISA_TANPA_PERISTIWA_SEBELUMNYA > 0
         THEN ROUND(100.0 * (KOLEKTE_RATA_RATA_PER_MISA_TANPA_PERISTIWA - KOLEKTE_PER_MISA_TANPA_PERISTIWA_SEBELUMNYA)
                    / KOLEKTE_PER_MISA_TANPA_PERISTIWA_SEBELUMNYA, 1) END AS PERTUMBUHAN_KOLEKTE_PER_MISA_TANPA_PERISTIWA_PERSEN,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM DENGAN_PEMBANDING;

-- 20. Trendlines and projection of income versus outcome ---------------------------------------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.PROYEKSI_PEMASUKAN_PENGELUARAN
    COMMENT = 'Garis tren linear dari tahun-tahun lengkap dan proyeksinya ke depan, serta tahun ketika tren pengeluaran melampaui tren kolekte. Metode sederhana. Data simulasi.'
AS
WITH LENGKAP AS (
    SELECT TAHUN, PEMASUKAN_KOLEKTE, TOTAL_PEMASUKAN, PENGELUARAN_PROGRAM
    FROM ANALISIS.PEMASUKAN_PENGELUARAN_TAHUNAN
    WHERE TAHUN_LENGKAP = TRUE
),
GARIS AS (
    SELECT
        MAX(TAHUN) AS TAHUN_LENGKAP_TERAKHIR,
        COUNT(*) AS JUMLAH_TAHUN_DASAR,
        REGR_SLOPE(PEMASUKAN_KOLEKTE, TAHUN) AS KEMIRINGAN_KOLEKTE,
        REGR_INTERCEPT(PEMASUKAN_KOLEKTE, TAHUN) AS TITIK_AWAL_KOLEKTE,
        REGR_SLOPE(TOTAL_PEMASUKAN, TAHUN) AS KEMIRINGAN_PEMASUKAN,
        REGR_INTERCEPT(TOTAL_PEMASUKAN, TAHUN) AS TITIK_AWAL_PEMASUKAN,
        REGR_SLOPE(PENGELUARAN_PROGRAM, TAHUN) AS KEMIRINGAN_PENGELUARAN,
        REGR_INTERCEPT(PENGELUARAN_PROGRAM, TAHUN) AS TITIK_AWAL_PENGELUARAN
    FROM LENGKAP
),
DAFTAR_TAHUN AS (
    SELECT TAHUN FROM ANALISIS.PEMASUKAN_PENGELUARAN_TAHUNAN
    UNION
    SELECT g.TAHUN_LENGKAP_TERAKHIR + h.N
    FROM GARIS g
    CROSS JOIN (VALUES (1), (2), (3), (4), (5)) AS h (N)
),
HITUNG AS (
    SELECT
        y.TAHUN,
        a.TAHUN_LENGKAP,
        a.PEMASUKAN_KOLEKTE AS KOLEKTE_AKTUAL,
        a.TOTAL_PEMASUKAN AS TOTAL_PEMASUKAN_AKTUAL,
        a.PENGELUARAN_PROGRAM AS PENGELUARAN_AKTUAL,
        g.TAHUN_LENGKAP_TERAKHIR,
        g.JUMLAH_TAHUN_DASAR,
        ROUND(g.KEMIRINGAN_KOLEKTE * y.TAHUN + g.TITIK_AWAL_KOLEKTE, 0) AS KOLEKTE_TREN,
        ROUND(g.KEMIRINGAN_PEMASUKAN * y.TAHUN + g.TITIK_AWAL_PEMASUKAN, 0) AS TOTAL_PEMASUKAN_TREN,
        ROUND(g.KEMIRINGAN_PENGELUARAN * y.TAHUN + g.TITIK_AWAL_PENGELUARAN, 0) AS PENGELUARAN_TREN,
        ROUND(g.KEMIRINGAN_KOLEKTE, 0) AS PERTAMBAHAN_KOLEKTE_PER_TAHUN,
        ROUND(g.KEMIRINGAN_PENGELUARAN, 0) AS PERTAMBAHAN_PENGELUARAN_PER_TAHUN
    FROM DAFTAR_TAHUN y
    CROSS JOIN GARIS g
    LEFT JOIN ANALISIS.PEMASUKAN_PENGELUARAN_TAHUNAN a ON a.TAHUN = y.TAHUN
)
SELECT
    h.TAHUN,
    CASE WHEN h.TAHUN <= h.TAHUN_LENGKAP_TERAKHIR THEN 'Aktual (tahun lengkap)'
         WHEN h.KOLEKTE_AKTUAL IS NOT NULL THEN 'Tahun berjalan (sebagian) dan proyeksi'
         ELSE 'Proyeksi' END AS JENIS_DATA,
    h.KOLEKTE_AKTUAL,
    h.TOTAL_PEMASUKAN_AKTUAL,
    h.PENGELUARAN_AKTUAL,
    h.KOLEKTE_TREN,
    h.TOTAL_PEMASUKAN_TREN,
    h.PENGELUARAN_TREN,
    h.KOLEKTE_TREN - h.PENGELUARAN_TREN AS SELISIH_TREN_KOLEKTE_VS_PENGELUARAN,
    h.TOTAL_PEMASUKAN_TREN - h.PENGELUARAN_TREN AS SELISIH_TREN_TOTAL_PEMASUKAN_VS_PENGELUARAN,
    CASE WHEN h.PENGELUARAN_TREN > h.KOLEKTE_TREN THEN TRUE ELSE FALSE END AS TREN_PENGELUARAN_MELEBIHI_KOLEKTE,
    MIN(CASE WHEN h.TAHUN > h.TAHUN_LENGKAP_TERAKHIR AND h.PENGELUARAN_TREN > h.KOLEKTE_TREN THEN h.TAHUN END) OVER ()
        AS TAHUN_PERTAMA_PENGELUARAN_MELEBIHI_KOLEKTE,
    MIN(CASE WHEN h.TAHUN > h.TAHUN_LENGKAP_TERAKHIR AND h.PENGELUARAN_TREN > h.TOTAL_PEMASUKAN_TREN THEN h.TAHUN END) OVER ()
        AS TAHUN_PERTAMA_PENGELUARAN_MELEBIHI_TOTAL_PEMASUKAN,
    h.PERTAMBAHAN_KOLEKTE_PER_TAHUN,
    h.PERTAMBAHAN_PENGELUARAN_PER_TAHUN,
    h.JUMLAH_TAHUN_DASAR,
    'Proyeksi garis lurus (regresi linear) dari tahun-tahun lengkap. Sederhana: tidak memperhitungkan peristiwa luar biasa maupun percepatan biaya.' AS CATATAN_METODE,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM HITUNG h;

-- 21. Donations per community: economic capacity, mean, median, total, per household -----------------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.SUMBANGAN_KELUARGA_PER_LINGKUNGAN
    COMMENT = 'Sumbangan kampanye per lingkungan: total, rata-rata, median, dan per keluarga atau umat terdaftar, beserta kapasitas ekonomi lingkungan. Menggambarkan sebaran, bukan menilai iman atau kemurahan hati. Data simulasi.'
AS
WITH KAMPANYE AS (
    SELECT k.ID_KAMPANYE, k.NAMA_KAMPANYE, k.PERIODE_MULAI, k.PERIODE_SELESAI, k.STATUS_KAMPANYE,
           LEAST(k.PERIODE_SELESAI, i.TANGGAL_SNAPSHOT) AS TANGGAL_ACUAN
    FROM DATA_OPERASIONAL.KAMPANYE_SUMBANGAN k
    CROSS JOIN MASTER_DATA.INFO_DATASET i
),
TERDAFTAR AS (
    SELECT k.ID_KAMPANYE, pl.ID_LINGKUNGAN,
           COUNT(DISTINCT pl.ID_KELUARGA) AS JUMLAH_KELUARGA_TERDAFTAR,
           COUNT(DISTINCT pk.ID_UMAT) AS JUMLAH_UMAT_TERDAFTAR
    FROM KAMPANYE k
    JOIN DATA_OPERASIONAL.PENUGASAN_LINGKUNGAN pl
        ON pl.TANGGAL_MULAI_BERLAKU <= k.TANGGAL_ACUAN
       AND (pl.TANGGAL_AKHIR_BERLAKU IS NULL OR pl.TANGGAL_AKHIR_BERLAKU >= k.TANGGAL_ACUAN)
    LEFT JOIN DATA_OPERASIONAL.PENUGASAN_KELUARGA pk
        ON pk.ID_KELUARGA = pl.ID_KELUARGA
       AND pk.TANGGAL_MULAI_BERLAKU <= k.TANGGAL_ACUAN
       AND (pk.TANGGAL_AKHIR_BERLAKU IS NULL OR pk.TANGGAL_AKHIR_BERLAKU >= k.TANGGAL_ACUAN)
    GROUP BY k.ID_KAMPANYE, pl.ID_LINGKUNGAN
),
SUMBANGAN AS (
    SELECT ID_KAMPANYE, ID_LINGKUNGAN,
           COUNT(*) AS JUMLAH_KELUARGA_PENYUMBANG,
           SUM(JUMLAH_SUMBANGAN) AS TOTAL_SUMBANGAN,
           AVG(JUMLAH_SUMBANGAN) AS RATA_RATA,
           MEDIAN(JUMLAH_SUMBANGAN) AS MEDIAN_SUMBANGAN,
           MAX(JUMLAH_SUMBANGAN) AS SUMBANGAN_TERBESAR
    FROM DATA_OPERASIONAL.SUMBANGAN_KELUARGA
    GROUP BY ID_KAMPANYE, ID_LINGKUNGAN
)
SELECT
    k.ID_KAMPANYE,
    k.NAMA_KAMPANYE,
    EXTRACT(YEAR FROM k.PERIODE_MULAI) AS TAHUN,
    w.NAMA_WILAYAH,
    l.ID_LINGKUNGAN,
    l.NAMA_LINGKUNGAN,
    pe.KATEGORI_EKONOMI,
    pe.INDEKS_KAPASITAS_EKONOMI,
    t.JUMLAH_KELUARGA_TERDAFTAR,
    t.JUMLAH_UMAT_TERDAFTAR,
    s.JUMLAH_KELUARGA_PENYUMBANG,
    s.TOTAL_SUMBANGAN,
    ROUND(s.RATA_RATA, 0) AS RATA_RATA_PER_KELUARGA_PENYUMBANG,
    ROUND(s.MEDIAN_SUMBANGAN, 0) AS MEDIAN_PER_KELUARGA_PENYUMBANG,
    ROUND(100.0 * (s.RATA_RATA - s.MEDIAN_SUMBANGAN) / NULLIF(s.MEDIAN_SUMBANGAN, 0), 1) AS SELISIH_RATA_RATA_DARI_MEDIAN_PERSEN,
    ROUND(100.0 * s.SUMBANGAN_TERBESAR / NULLIF(s.TOTAL_SUMBANGAN, 0), 1) AS PERSEN_TOTAL_DARI_SUMBANGAN_TERBESAR,
    ROUND(1.0 * s.TOTAL_SUMBANGAN / NULLIF(t.JUMLAH_KELUARGA_TERDAFTAR, 0), 0) AS SUMBANGAN_PER_KELUARGA_TERDAFTAR,
    ROUND(1.0 * s.TOTAL_SUMBANGAN / NULLIF(t.JUMLAH_UMAT_TERDAFTAR, 0), 0) AS SUMBANGAN_PER_UMAT_TERDAFTAR,
    'Menggambarkan kapasitas ekonomi dan sebaran sumbangan, bukan tingkat iman atau kemurahan hati. Jangan dipakai untuk memeringkat lingkungan.' AS CATATAN_PENGGUNAAN,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM SUMBANGAN s
JOIN KAMPANYE k ON k.ID_KAMPANYE = s.ID_KAMPANYE
JOIN MASTER_DATA.MASTER_LINGKUNGAN l ON l.ID_LINGKUNGAN = s.ID_LINGKUNGAN
JOIN MASTER_DATA.MASTER_WILAYAH w ON w.ID_WILAYAH = l.ID_WILAYAH
JOIN MASTER_DATA.PROFIL_EKONOMI_LINGKUNGAN pe ON pe.ID_LINGKUNGAN = l.ID_LINGKUNGAN
LEFT JOIN TERDAFTAR t ON t.ID_KAMPANYE = s.ID_KAMPANYE AND t.ID_LINGKUNGAN = s.ID_LINGKUNGAN;

-- 22. Break-even: does a campaign cover the celebration it pays for? ----------------------------------------------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.TITIK_IMPAS_KAMPANYE
    COMMENT = 'Sumbangan kampanye (Prapaskah, Adven, solidaritas) dibandingkan dengan biaya kegiatan besar yang didanainya, per tahun. Surplus menjadi pemasukan gereja, defisit ditutup gereja. Data simulasi.'
AS
WITH SUMBANGAN AS (
    SELECT ID_KAMPANYE, COUNT(*) AS JUMLAH_KELUARGA_PENYUMBANG, SUM(JUMLAH_SUMBANGAN) AS TOTAL_SUMBANGAN
    FROM DATA_OPERASIONAL.SUMBANGAN_KELUARGA
    GROUP BY ID_KAMPANYE
)
SELECT
    k.ID_KAMPANYE,
    k.NAMA_KAMPANYE,
    EXTRACT(YEAR FROM k.PERIODE_MULAI) AS TAHUN,
    o.NAMA_KESEMPATAN,
    k.STATUS_KAMPANYE,
    k.TARGET_DANA,
    COALESCE(s.JUMLAH_KELUARGA_PENYUMBANG, 0) AS JUMLAH_KELUARGA_PENYUMBANG,
    COALESCE(s.TOTAL_SUMBANGAN, 0) AS TOTAL_SUMBANGAN,
    p.NAMA_PROGRAM AS KEGIATAN_YANG_DIDANAI,
    p.STATUS_PELAKSANAAN AS STATUS_KEGIATAN,
    p.ANGGARAN_RENCANA,
    p.ANGGARAN_TERPAKAI AS BIAYA_AKTUAL,
    CASE WHEN p.STATUS_PELAKSANAAN = 'Terlaksana' THEN COALESCE(s.TOTAL_SUMBANGAN, 0) - p.ANGGARAN_TERPAKAI END AS SELISIH_SUMBANGAN_VS_BIAYA_AKTUAL,
    CASE WHEN p.STATUS_PELAKSANAAN = 'Terlaksana' AND p.ANGGARAN_TERPAKAI > 0
         THEN ROUND(100.0 * COALESCE(s.TOTAL_SUMBANGAN, 0) / p.ANGGARAN_TERPAKAI, 1) END AS PERSEN_BIAYA_TERTUTUP_SUMBANGAN,
    CASE WHEN p.STATUS_PELAKSANAAN = 'Terlaksana' AND COALESCE(s.TOTAL_SUMBANGAN, 0) >= p.ANGGARAN_TERPAKAI
         THEN COALESCE(s.TOTAL_SUMBANGAN, 0) - p.ANGGARAN_TERPAKAI END AS PEMASUKAN_BERSIH_UNTUK_GEREJA,
    CASE WHEN p.STATUS_PELAKSANAAN = 'Terlaksana' AND COALESCE(s.TOTAL_SUMBANGAN, 0) < p.ANGGARAN_TERPAKAI
         THEN p.ANGGARAN_TERPAKAI - COALESCE(s.TOTAL_SUMBANGAN, 0) END AS DANA_TAMBAHAN_DARI_GEREJA,
    CASE WHEN p.ID_RENCANA IS NULL THEN 'Tidak ada kegiatan yang didanai'
         WHEN p.STATUS_PELAKSANAAN <> 'Terlaksana' THEN 'Belum dapat dihitung (kegiatan belum terlaksana)'
         WHEN COALESCE(s.TOTAL_SUMBANGAN, 0) >= p.ANGGARAN_TERPAKAI THEN 'Surplus: kelebihan dana menjadi pemasukan gereja'
         ELSE 'Defisit: gereja perlu menambah dana'
    END AS STATUS_TITIK_IMPAS,
    CASE WHEN p.STATUS_PELAKSANAAN <> 'Terlaksana' THEN k.TARGET_DANA - p.ANGGARAN_RENCANA END AS PROYEKSI_SELISIH_JIKA_TARGET_TERCAPAI,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM DATA_OPERASIONAL.KAMPANYE_SUMBANGAN k
JOIN MASTER_DATA.REFERENSI_KESEMPATAN_KHUSUS o
    ON o.ID_KESEMPATAN = k.ID_KESEMPATAN
LEFT JOIN SUMBANGAN s
    ON s.ID_KAMPANYE = k.ID_KAMPANYE
LEFT JOIN ANALISIS.ANGGARAN_VS_REALISASI_PROGRAM p
    ON p.ID_RENCANA = k.ID_RENCANA_PENGGUNAAN;

-- 23. Upcoming activities: from the annual plan to a scheduled event -------------------------------------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.KEGIATAN_MENDATANG
    COMMENT = 'Kegiatan yang akan datang, satu baris per rencana yang belum terlaksana: sudah dijadwalkan sebagai kegiatan, masih berupa rencana tahunan, atau ditunda tahun ini dan perlu jadwal baru. Lengkap dengan tanggal, tempat, target peserta, anggaran, dan dana pendukung. Acuan waktu adalah tanggal data. Data simulasi.'
AS
WITH DANA AS (
    SELECT ID_RENCANA_PENGGUNAAN AS ID_RENCANA,
           MIN(NAMA_KAMPANYE) AS NAMA_KAMPANYE,
           SUM(TARGET_DANA) AS TARGET_DANA
    FROM DATA_OPERASIONAL.KAMPANYE_SUMBANGAN
    WHERE ID_RENCANA_PENGGUNAAN IS NOT NULL
    GROUP BY ID_RENCANA_PENGGUNAAN
)
SELECT
    p.ID_RENCANA,
    p.TAHUN_RENCANA,
    p.ID_SEKSI,
    p.NAMA_SEKSI,
    p.NAMA_PROGRAM,
    CASE WHEN p.STATUS_PELAKSANAAN = 'Ditunda' THEN 'Ditunda, perlu jadwal baru'
         WHEN g.ID_KEGIATAN IS NOT NULL THEN 'Sudah dijadwalkan'
         ELSE 'Masih rencana tahunan'
    END AS TAHAP,
    p.STATUS_PELAKSANAAN AS STATUS_RENCANA,
    g.ID_KEGIATAN,
    COALESCE(g.TANGGAL_MULAI, p.TANGGAL_RENCANA) AS TANGGAL_MULAI,
    COALESCE(g.TANGGAL_SELESAI, p.TANGGAL_RENCANA) AS TANGGAL_SELESAI,
    DATEDIFF('day', i.TANGGAL_SNAPSHOT, COALESCE(g.TANGGAL_MULAI, p.TANGGAL_RENCANA)) AS HARI_DARI_TANGGAL_DATA,
    g.LOKASI,
    g.TARGET_PESERTA,
    p.ANGGARAN_RENCANA,
    g.KETERANGAN AS CATATAN_KEGIATAN,
    d.NAMA_KAMPANYE AS DIDANAI_KAMPANYE,
    d.TARGET_DANA AS TARGET_DANA_KAMPANYE,
    CASE WHEN d.ID_RENCANA IS NOT NULL THEN d.TARGET_DANA - p.ANGGARAN_RENCANA END AS SELISIH_TARGET_DANA_VS_ANGGARAN,
    i.TANGGAL_SNAPSHOT AS TANGGAL_DATA,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM ANALISIS.ANGGARAN_VS_REALISASI_PROGRAM p
CROSS JOIN MASTER_DATA.INFO_DATASET i
LEFT JOIN DATA_OPERASIONAL.KEGIATAN g
    ON g.ID_RENCANA = p.ID_RENCANA
LEFT JOIN DANA d
    ON d.ID_RENCANA = p.ID_RENCANA
WHERE p.STATUS_PELAKSANAAN = 'Direncanakan'
   OR (p.STATUS_PELAKSANAAN = 'Ditunda' AND p.TAHUN_RENCANA = EXTRACT(YEAR FROM i.TANGGAL_SNAPSHOT));

-- =============================================================================
-- Shadow forecast of the weekly offertory: forecast against actual, with the events that explain the gap
-- =============================================================================

-- 24. Weekly offertory against the shadow forecast ---------------------------------------------------------------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.KOLEKTE_AKTUAL_VS_PERKIRAAN
    COMMENT = 'Kolekte mingguan sebenarnya dibandingkan dengan perkiraan bayangan yang dibuat empat pekan sebelumnya, lengkap dengan rentang perkiraan, selisih, dan peristiwa luar biasa yang menjelaskan selisih besar. Hanya pekan yang sudah lengkap pada tanggal data yang dibandingkan. Data simulasi.'
AS
WITH DASAR AS (
    SELECT
        p.ID_MODEL,
        p.AWAL_PEKAN_SASARAN,
        p.TANGGAL_PERKIRAAN,
        p.JUMLAH_PEKAN_PELATIHAN,
        p.JUMLAH_PERKIRAAN,
        p.BATAS_BAWAH,
        p.BATAS_ATAS,
        p.PENYESUAIAN_KALENDER,
        p.KETERANGAN,
        CASE WHEN DATEADD('day', 6, p.AWAL_PEKAN_SASARAN) <= i.TANGGAL_SNAPSHOT THEN 'Lengkap'
             WHEN p.AWAL_PEKAN_SASARAN <= i.TANGGAL_SNAPSHOT THEN 'Sedang berjalan'
             ELSE 'Mendatang'
        END AS STATUS_PEKAN
    FROM DATA_OPERASIONAL.PERKIRAAN_KOLEKTE_MINGGUAN p
    CROSS JOIN MASTER_DATA.INFO_DATASET i
),
DENGAN_AKTUAL AS (
    SELECT
        d.*,
        CASE WHEN d.STATUS_PEKAN = 'Lengkap' THEN COALESCE(w.TOTAL_KOLEKTE, 0) END AS KOLEKTE_AKTUAL,
        w.ID_PERISTIWA,
        w.JENIS_PERISTIWA,
        w.NAMA_PERISTIWA,
        w.TINGKAT_GANGGUAN
    FROM DASAR d
    LEFT JOIN ANALISIS.KOLEKTE_MINGGUAN_DAN_PERISTIWA w
        ON w.AWAL_PEKAN = d.AWAL_PEKAN_SASARAN
)
SELECT
    a.AWAL_PEKAN_SASARAN AS AWAL_PEKAN,
    EXTRACT(YEAR FROM a.AWAL_PEKAN_SASARAN) AS TAHUN,
    a.ID_MODEL,
    m.NAMA_MODEL,
    m.LEBAR_RENTANG_PERSEN,
    a.TANGGAL_PERKIRAAN,
    a.STATUS_PEKAN,
    a.JUMLAH_PERKIRAAN,
    a.BATAS_BAWAH,
    a.BATAS_ATAS,
    a.KOLEKTE_AKTUAL,
    a.KOLEKTE_AKTUAL - a.JUMLAH_PERKIRAAN AS SELISIH,
    ROUND(100.0 * (a.KOLEKTE_AKTUAL - a.JUMLAH_PERKIRAAN) / NULLIF(a.JUMLAH_PERKIRAAN, 0), 1) AS SELISIH_PERSEN,
    CASE WHEN a.KOLEKTE_AKTUAL IS NULL THEN NULL
         WHEN a.KOLEKTE_AKTUAL < a.BATAS_BAWAH THEN 'Di bawah rentang'
         WHEN a.KOLEKTE_AKTUAL > a.BATAS_ATAS THEN 'Di atas rentang'
         ELSE 'Dalam rentang'
    END AS POSISI_TERHADAP_RENTANG,
    CASE WHEN a.ID_PERISTIWA IS NOT NULL THEN 'Peristiwa luar biasa'
         WHEN a.KETERANGAN IS NOT NULL THEN 'Hari raya atau kolekte khusus'
         ELSE 'Pekan biasa'
    END AS JENIS_PEKAN,
    CASE WHEN a.KOLEKTE_AKTUAL IS NULL THEN NULL
         WHEN a.KOLEKTE_AKTUAL BETWEEN a.BATAS_BAWAH AND a.BATAS_ATAS THEN 'Dalam rentang perkiraan'
         WHEN a.ID_PERISTIWA IS NOT NULL THEN 'Di luar rentang, dijelaskan peristiwa luar biasa'
         ELSE 'Di luar rentang, tanpa peristiwa tercatat'
    END AS PENJELASAN_SELISIH,
    a.PENYESUAIAN_KALENDER,
    a.KETERANGAN AS CATATAN_KALENDER,
    a.JUMLAH_PEKAN_PELATIHAN,
    a.ID_PERISTIWA,
    a.JENIS_PERISTIWA,
    a.NAMA_PERISTIWA,
    a.TINGKAT_GANGGUAN,
    'Selisih = kolekte sebenarnya dikurangi perkiraan. Negatif berarti kolekte lebih rendah dari perkiraan.' AS CATATAN_METODE,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM DENGAN_AKTUAL a
JOIN MASTER_DATA.REFERENSI_MODEL_PERKIRAAN m
    ON m.ID_MODEL = a.ID_MODEL;

-- 25. Gap between forecast and actual for each unforeseen event ----------------------------------------------------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.BIAS_PERKIRAAN_PER_PERISTIWA
    COMMENT = 'Untuk setiap peristiwa luar biasa: seberapa jauh kolekte sebenarnya menyimpang dari perkiraan bayangan selama pekan-pekan peristiwa, dibandingkan dengan galat biasa pada pekan tanpa peristiwa. Menjelaskan mengapa perkiraan meleset. Data simulasi.'
AS
WITH GALAT_BIASA AS (
    SELECT ID_MODEL,
           AVG(100.0 * ABS(KOLEKTE_AKTUAL - JUMLAH_PERKIRAAN) / NULLIF(JUMLAH_PERKIRAAN, 0)) AS GALAT_PERSEN
    FROM ANALISIS.KOLEKTE_AKTUAL_VS_PERKIRAAN
    WHERE STATUS_PEKAN = 'Lengkap' AND JENIS_PEKAN = 'Pekan biasa'
    GROUP BY ID_MODEL
),
PER_PERISTIWA AS (
    SELECT
        v.ID_MODEL,
        v.ID_PERISTIWA,
        COUNT(*) AS JUMLAH_PEKAN_TERDAMPAK,
        MIN(v.AWAL_PEKAN) AS PEKAN_PERTAMA,
        MAX(v.AWAL_PEKAN) AS PEKAN_TERAKHIR,
        SUM(v.JUMLAH_PERKIRAAN) AS PERKIRAAN_TOTAL,
        SUM(v.KOLEKTE_AKTUAL) AS KOLEKTE_AKTUAL_TOTAL,
        SUM(CASE WHEN v.POSISI_TERHADAP_RENTANG <> 'Dalam rentang' THEN 1 ELSE 0 END) AS JUMLAH_PEKAN_DI_LUAR_RENTANG,
        MIN(v.SELISIH_PERSEN) AS SELISIH_PERSEN_TERBESAR_NEGATIF
    FROM ANALISIS.KOLEKTE_AKTUAL_VS_PERKIRAAN v
    WHERE v.STATUS_PEKAN = 'Lengkap' AND v.ID_PERISTIWA IS NOT NULL
    GROUP BY v.ID_MODEL, v.ID_PERISTIWA
)
SELECT
    e.ID_PERISTIWA,
    e.JENIS_PERISTIWA,
    e.NAMA_PERISTIWA,
    e.TANGGAL_MULAI,
    e.TANGGAL_SELESAI,
    e.TINGKAT_GANGGUAN,
    e.DESKRIPSI,
    g.ID_MODEL,
    g.JUMLAH_PEKAN_TERDAMPAK,
    g.PEKAN_PERTAMA,
    g.PEKAN_TERAKHIR,
    g.PERKIRAAN_TOTAL,
    g.KOLEKTE_AKTUAL_TOTAL,
    g.KOLEKTE_AKTUAL_TOTAL - g.PERKIRAAN_TOTAL AS SELISIH_TOTAL,
    ROUND(100.0 * (g.KOLEKTE_AKTUAL_TOTAL - g.PERKIRAAN_TOTAL) / NULLIF(g.PERKIRAAN_TOTAL, 0), 1) AS SELISIH_PERSEN,
    g.SELISIH_PERSEN_TERBESAR_NEGATIF,
    g.JUMLAH_PEKAN_DI_LUAR_RENTANG,
    ROUND(b.GALAT_PERSEN, 1) AS GALAT_PEKAN_BIASA_PERSEN,
    ROUND(ABS(100.0 * (g.KOLEKTE_AKTUAL_TOTAL - g.PERKIRAAN_TOTAL) / NULLIF(g.PERKIRAAN_TOTAL, 0)) / NULLIF(b.GALAT_PERSEN, 0), 1) AS KELIPATAN_GALAT_BIASA,
    'Pekan tanpa peristiwa dan tanpa hari raya dipakai sebagai ukuran galat biasa. Peristiwa sebelum perkiraan pertama (Agustus 2021) tidak tercantum.' AS CATATAN_METODE,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM PER_PERISTIWA g
JOIN DATA_OPERASIONAL.PERISTIWA_LUAR_BIASA e
    ON e.ID_PERISTIWA = g.ID_PERISTIWA
LEFT JOIN GALAT_BIASA b
    ON b.ID_MODEL = g.ID_MODEL;

-- 26. Forecast accuracy per year and kind of week --------------------------------------------------------------------------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.AKURASI_PERKIRAAN_TAHUNAN
    COMMENT = 'Ketepatan perkiraan bayangan per tahun dan jenis pekan (pekan biasa, hari raya atau kolekte khusus, peristiwa luar biasa): galat rata-rata, selisih rata-rata, dan persentase pekan yang jatuh di dalam rentang perkiraan. Data simulasi.'
AS
SELECT
    v.TAHUN,
    v.JENIS_PEKAN,
    v.ID_MODEL,
    v.LEBAR_RENTANG_PERSEN,
    COUNT(*) AS JUMLAH_PEKAN,
    ROUND(AVG(100.0 * ABS(v.KOLEKTE_AKTUAL - v.JUMLAH_PERKIRAAN) / NULLIF(v.JUMLAH_PERKIRAAN, 0)), 1) AS GALAT_RATA_RATA_PERSEN,
    ROUND(AVG(100.0 * (v.KOLEKTE_AKTUAL - v.JUMLAH_PERKIRAAN) / NULLIF(v.JUMLAH_PERKIRAAN, 0)), 1) AS SELISIH_RATA_RATA_PERSEN,
    SUM(CASE WHEN v.POSISI_TERHADAP_RENTANG = 'Dalam rentang' THEN 1 ELSE 0 END) AS JUMLAH_DALAM_RENTANG,
    ROUND(100.0 * SUM(CASE WHEN v.POSISI_TERHADAP_RENTANG = 'Dalam rentang' THEN 1 ELSE 0 END) / COUNT(*), 1) AS PERSEN_DALAM_RENTANG,
    'Galat = rata-rata selisih mutlak terhadap perkiraan. Selisih rata-rata negatif berarti kolekte lebih rendah dari perkiraan.' AS CATATAN_METODE,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM ANALISIS.KOLEKTE_AKTUAL_VS_PERKIRAAN v
WHERE v.STATUS_PEKAN = 'Lengkap'
GROUP BY v.TAHUN, v.JENIS_PEKAN, v.ID_MODEL, v.LEBAR_RENTANG_PERSEN;

-- =============================================================================
-- Public service guides: what a parishioner may read without logging in
-- =============================================================================

-- 27. Public services -------------------------------------------------------------------------------------------------------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.LAYANAN_PUBLIK
    COMMENT = 'Layanan paroki yang boleh dibaca umum (klasifikasi yang dapat tampil publik): ringkasan, waktu proses, seksi pengelola, nama berkas PDF panduan, dan jumlah langkah serta persyaratan. Isi panduan fiktif dan bukan ketentuan resmi. Data simulasi.'
AS
SELECT
    l.ID_LAYANAN,
    l.NAMA_LAYANAN,
    l.KATEGORI_LAYANAN,
    l.RINGKASAN,
    l.PERKIRAAN_WAKTU_PROSES,
    l.CATATAN_PENTING,
    s.NAMA_SEKSI AS SEKSI_PENGELOLA,
    l.NAMA_BERKAS_PANDUAN,
    l.TANGGAL_REVISI,
    COALESCE(g.JUMLAH_LANGKAH, 0) AS JUMLAH_LANGKAH,
    COALESCE(p.JUMLAH_PERSYARATAN, 0) AS JUMLAH_PERSYARATAN,
    COALESCE(p.JUMLAH_WAJIB, 0) AS JUMLAH_PERSYARATAN_WAJIB,
    'Panduan contoh untuk demonstrasi, bukan ketentuan resmi gereja, keuskupan, atau paroki mana pun.' AS CATATAN_PENGGUNAAN,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM MASTER_DATA.LAYANAN_PAROKI l
JOIN MASTER_DATA.REFERENSI_KLASIFIKASI_DATA k
    ON k.ID_KLASIFIKASI_DATA = l.ID_KLASIFIKASI_DATA
   AND k.DAPAT_DITAMPILKAN_PUBLIK = TRUE
JOIN MASTER_DATA.MASTER_SEKSI s
    ON s.ID_SEKSI = l.ID_SEKSI_PENGELOLA
LEFT JOIN (
    SELECT ID_LAYANAN, COUNT(*) AS JUMLAH_LANGKAH
    FROM MASTER_DATA.LANGKAH_LAYANAN
    GROUP BY ID_LAYANAN
) g ON g.ID_LAYANAN = l.ID_LAYANAN
LEFT JOIN (
    SELECT ID_LAYANAN,
           COUNT(*) AS JUMLAH_PERSYARATAN,
           SUM(CASE WHEN WAJIB_DIPENUHI THEN 1 ELSE 0 END) AS JUMLAH_WAJIB
    FROM MASTER_DATA.PERSYARATAN_LAYANAN
    GROUP BY ID_LAYANAN
) p ON p.ID_LAYANAN = l.ID_LAYANAN;

-- 28. Steps of the public services -------------------------------------------------------------------------------------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.LANGKAH_LAYANAN_PUBLIK
    COMMENT = 'Langkah berurutan setiap layanan publik, dengan pelaku langkah (pemohon, sekretariat, pastor, seksi, atau ketua lingkungan). Hanya layanan yang boleh dibaca umum. Data simulasi.'
AS
SELECT
    g.ID_LAYANAN,
    l.NAMA_LAYANAN,
    l.KATEGORI_LAYANAN,
    g.NOMOR_URUT,
    g.JUDUL_LANGKAH,
    g.URAIAN,
    g.PELAKU,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM MASTER_DATA.LANGKAH_LAYANAN g
JOIN ANALISIS.LAYANAN_PUBLIK l
    ON l.ID_LAYANAN = g.ID_LAYANAN;

-- 29. Requirements of the public services --------------------------------------------------------------------------------------------------------------------------
CREATE OR REPLACE VIEW ANALISIS.PERSYARATAN_LAYANAN_PUBLIK
    COMMENT = 'Persyaratan setiap layanan publik: dokumen, pembinaan, dan ketentuan umum, ditandai wajib atau hanya jika berlaku. Hanya layanan yang boleh dibaca umum. Data simulasi.'
AS
SELECT
    r.ID_LAYANAN,
    l.NAMA_LAYANAN,
    l.KATEGORI_LAYANAN,
    r.NOMOR_URUT,
    r.NAMA_PERSYARATAN,
    r.JENIS_PERSYARATAN,
    CASE WHEN r.WAJIB_DIPENUHI THEN 'Wajib' ELSE 'Jika berlaku' END AS STATUS_PERSYARATAN,
    r.KETERANGAN,
    'Data simulasi (fiktif)' AS SUMBER_DATA
FROM MASTER_DATA.PERSYARATAN_LAYANAN r
JOIN ANALISIS.LAYANAN_PUBLIK l
    ON l.ID_LAYANAN = r.ID_LAYANAN;

